function worldRects(rec,v,w){
  // Candidate block-footprint window (2px slack around the envelope): keeps the
  // shelf block's own rects while excluding room floor tints, walls and glows
  // that merely overlap the vicinity with wider/other geometry.
  return rec.rects.filter(q=>q.mode==='fill').map(q=>({
    x:(q.x-v.x)/v.scale,y:(q.y-v.y)/v.scale,w:q.w/v.scale,h:q.h/v.scale,color:q.color
  })).filter(r=>r.x>=w.x-2-1e-6&&r.x+r.w<=w.x+w.w+17+1e-6&&
    r.y>=w.y-38-1e-6&&r.y+r.h<=w.y+w.h+12+1e-6);
}
function worldEllipses(rec,v,w){
  const e=env(w);
  return rec.shapes.filter(s=>s.type==='ellipse').map(s=>({
    x:(s.x-v.x)/v.scale,y:(s.y-v.y)/v.scale,rx:s.rx/v.scale,ry:s.ry/v.scale,
    color:s.color,mode:s.mode
  })).filter(s=>centerIn(s.x,s.y,e));
}
function worldTexts(rec,v,w){
  const e=env(w);
  return rec.texts.map(t=>({text:t.text,x:(t.x-v.x)/v.scale,y:(t.y-v.y)/v.scale}))
    .filter(t=>centerIn(t.x,t.y,e));
}

